    m.write32(r.esp.wrapping_add(8), r.xmm[1].f(0).to_bits());
    r.ecx = m.read32(r.esp.wrapping_add(8));
    r.xmm[1] = Xmm::scalar(f32::from_bits(m.read32(r.esp.wrapping_add(0xc))).to_bits());
    r.ecx = r.ecx & 0x7fffffff;
    m.write32(r.esp.wrapping_add(8), r.ecx);
    fca = f32::from_bits(r.xmm[1].lanes[0]) as f64;
    fcb = f32::from_bits(m.read32(r.esp.wrapping_add(8))) as f64;
    if (fca <= fcb) || ((fca != fca) || (fcb != fcb)) {
        fca = f32::from_bits(r.xmm[0].lanes[0]) as f64;
        fcb = f32::from_bits(m.read32(r.eax)) as f64;
        r.xmm[0] = Xmm::scalar(f32::from_bits(m.read32(r.eax)).to_bits());
        if (fca <= fcb) || ((fca != fca) || (fcb != fcb)) {
            r.xmm[0].set_f(0, r.xmm[0].f(0) - r.xmm[1].f(0));
            m.write32(r.eax, r.xmm[0].f(0).to_bits());
            r.eax = 0;
            return;
        }
        r.xmm[0].set_f(0, r.xmm[0].f(0) + r.xmm[1].f(0));
        m.write32(r.eax, r.xmm[0].f(0).to_bits());
        r.eax = 0;
        return;
    } else {
        m.write32(r.eax, r.xmm[0].f(0).to_bits());
        r.eax = 1;
        return;
    }
