/// Functions in this module (differential entry points; not admitted to any selector).
pub const ROOTS: [u32; 4] = [0x59320, 0x1515e0, 0x153b00, 0x150580];

/// Differential entry: runs the translation of `va`. True when `va` belongs to this module.
#[allow(unused_variables)]
pub fn run<M: GuestMemory, C: GuestCall>(
    va: u32,
    m: &mut M,
    guest: &mut C,
    regs: &mut ExtRegisters,
) -> bool {
    match va {
        0x59320 => game_anim_decode_node_key_transform_scaled(m, guest, regs),
        0x1515e0 => game_float_approach_target_step_returns_arrived(m, regs),
        0x153b00 => game_rdtsc_store_as_float_scaled_to_global(m, regs),
        0x150580 => game_quat_multiply_to_out(m, regs),
        _ => return false,
    }
    true
}
